/**
 * Cache for platform detection functions.
 */
interface PlatformCache {
  _cached?: boolean | string;
}

/**
 * Cached function type.
 */
export type CachedFunction<T> = (() => T) & PlatformCache;

import { isBrowser } from '../browser';

import type { CachedFunction } from './cache';
import type { Browser } from './platform.types';

/**
 * Detects the browser from user agent.
 *
 * Returns the detected browser or 'Unknown' if unable to detect.
 * This is cached for performance.
 *
 * **Key Features**:
 * - User agent parsing
 * - Detects major browsers
 * - SSR-safe
 * - Cached result
 *
 * @returns Browser type (null in SSR)
 *
 * @example
 * ```tsx
 * function BrowserWarning() {
 *   const browser = getBrowser();
 *
 *   if (browser === 'Safari' && parseInt(navigator.userAgent.match(/Version\/(\d+)/)?.[1] || '0') < 14) {
 *     return <div>Please update Safari for the best experience</div>;
 *   }
 *
 *   return null;
 * }
 * ```
 *
 * @example
 * ```tsx
 * // Browser-specific CSS class
 * function App() {
 *   const browser = getBrowser();
 *
 *   return (
 *     <div className={`app browser-${browser?.toLowerCase()}`}>
 *       <Content />
 *     </div>
 *   );
 * }
 * ```
 */
export function getBrowser(): Browser | null {
  if (!isBrowser()) {
    return null;
  }

  // Cache the result
  const cached = (getBrowser as CachedFunction<Browser | null>)._cached;
  if (typeof cached === 'string') {
    return cached as Browser;
  }

  const userAgent = navigator.userAgent.toLowerCase();

  let browser: Browser = 'Unknown';

  // Order matters: check for more specific browsers first
  if (userAgent.includes('edg')) {
    browser = 'Edge';
  } else if (userAgent.includes('opr') || userAgent.includes('opera')) {
    browser = 'Opera';
  } else if (userAgent.includes('samsungbrowser')) {
    browser = 'Samsung';
  } else if (userAgent.includes('chrome')) {
    browser = 'Chrome';
  } else if (userAgent.includes('safari')) {
    browser = 'Safari';
  } else if (userAgent.includes('firefox')) {
    browser = 'Firefox';
  }

  // Cache the result
  (getBrowser as CachedFunction<Browser | null>)._cached = browser;

  return browser;
}

import { isBrowser } from '../browser';

/**
 * Gets the device pixel ratio for high-DPI displays.
 *
 * Returns the ratio of physical pixels to CSS pixels. Useful for
 * loading appropriate image resolutions or canvas scaling.
 *
 * **Key Features**:
 * - Returns window.devicePixelRatio
 * - Defaults to 1 if unavailable
 * - SSR-safe
 *
 * @returns Device pixel ratio (1 in SSR)
 *
 * @example
 * ```tsx
 * function HiDPIImage({ src }: { src: string }) {
 *   const dpr = getDevicePixelRatio();
 *   const imageSrc = dpr && dpr >= 2 ? `${src}@2x.png` : `${src}.png`;
 *
 *   return <img src={imageSrc} alt="High DPI aware" />;
 * }
 * ```
 *
 * @example
 * ```tsx
 * // Canvas scaling for Retina displays
 * function CanvasDrawing() {
 *   const canvasRef = useRef<HTMLCanvasElement>(null);
 *
 *   useEffect(() => {
 *     const canvas = canvasRef.current;
 *     if (!canvas) return;
 *
 *     const ctx = canvas.getContext('2d');
 *     const dpr = getDevicePixelRatio() || 1;
 *
 *     // Scale canvas for high DPI
 *     canvas.width = canvas.offsetWidth * dpr;
 *     canvas.height = canvas.offsetHeight * dpr;
 *     ctx?.scale(dpr, dpr);
 *   }, []);
 *
 *   return <canvas ref={canvasRef} />;
 * }
 * ```
 */
export function getDevicePixelRatio(): number | null {
  if (!isBrowser()) {
    return null;
  }

  return window.devicePixelRatio || 1;
}

import { isBrowser } from '../browser';

import type { CachedFunction } from './cache';
import type { OperatingSystem } from './platform.types';

/**
 * Detects the operating system from user agent.
 *
 * Returns the detected OS or 'Unknown' if unable to detect.
 * This is cached for performance.
 *
 * **Key Features**:
 * - User agent parsing
 * - Platform API fallback
 * - SSR-safe
 * - Cached result
 *
 * @returns Operating system type (null in SSR)
 *
 * @example
 * ```tsx
 * function OSSpecificInstructions() {
 *   const os = getOS();
 *
 *   if (os === 'macOS') {
 *     return <p>Press Cmd+C to copy</p>;
 *   }
 *
 *   return <p>Press Ctrl+C to copy</p>;
 * }
 * ```
 *
 * @example
 * ```tsx
 * // Download appropriate installer
 * function DownloadButton() {
 *   const os = getOS();
 *   const downloadUrl = os === 'Windows' ? '/app.exe' :
 *                       os === 'macOS' ? '/app.dmg' :
 *                       '/app.tar.gz';
 *
 *   return <a href={downloadUrl}>Download for {os}</a>;
 * }
 * ```
 */
export function getOS(): OperatingSystem | null {
  if (!isBrowser()) {
    return null;
  }

  // Cache the result
  const cached = (getOS as CachedFunction<OperatingSystem | null>)._cached;
  if (typeof cached === 'string') {
    return cached as OperatingSystem;
  }

  const userAgent = navigator.userAgent.toLowerCase();
  const platform = navigator.platform?.toLowerCase() || '';

  let os: OperatingSystem = 'Unknown';

  if (/iphone|ipad|ipod/i.test(userAgent)) {
    os = 'iOS';
  } else if (/android/i.test(userAgent)) {
    os = 'Android';
  } else if (/win/i.test(platform)) {
    os = 'Windows';
  } else if (/mac/i.test(platform)) {
    os = 'macOS';
  } else if (/linux/i.test(platform)) {
    os = 'Linux';
  }

  // Cache the result
  (getOS as CachedFunction<OperatingSystem | null>)._cached = os;

  return os;
}

import { isBrowser } from '../browser';

import { isRTL } from './isRTL';

import type { TextDirection } from './platform.types';

/**
 * Gets the text direction (ltr or rtl) of the document.
 *
 * Uses isRTL() to determine direction. Returns 'ltr' by default.
 *
 * **Key Features**:
 * - Returns TextDirection type
 * - SSR-safe
 * - Cached via isRTL
 *
 * @returns Text direction ('ltr' or 'rtl', null in SSR)
 *
 * @example
 * ```tsx
 * function Breadcrumb() {
 *   const direction = getTextDirection();
 *   const separator = direction === 'rtl' ? '←' : '→';
 *
 *   return (
 *     <nav>
 *       Home {separator} Products {separator} Item
 *     </nav>
 *   );
 * }
 * ```
 *
 * @example
 * ```tsx
 * // Apply direction to component
 * function Container() {
 *   const direction = getTextDirection();
 *
 *   return (
 *     <div dir={direction || undefined}>
 *       <Content />
 *     </div>
 *   );
 * }
 * ```
 */
export function getTextDirection(): TextDirection | null {
  if (!isBrowser()) {
    return null;
  }

  return isRTL() ? 'rtl' : 'ltr';
}

import { isBrowser } from '../browser';

import type { CachedFunction } from './cache';

/**
 * Detects if the device has hover capability (fine pointer).
 *
 * Uses pointer media queries to detect if the primary input mechanism
 * can hover over elements. Returns false for touch-only devices.
 *
 * **Key Features**:
 * - Media query detection
 * - Distinguishes fine vs coarse pointer
 * - SSR-safe
 * - Cached result
 *
 * @returns True if device has hover, false otherwise (null in SSR)
 *
 * @example
 * ```tsx
 * function InteractiveCard() {
 *   const canHover = hasHover();
 *
 *   return (
 *     <div
 *       className={canHover ? 'hoverable' : 'touch-friendly'}
 *       // Only add hover effects if device supports it
 *       onMouseEnter={canHover ? handleHover : undefined}
 *     >
 *       Card content
 *     </div>
 *   );
 * }
 * ```
 *
 * @example
 * ```tsx
 * // Conditional tooltip
 * function TooltipWrapper({ children, tooltip }: Props) {
 *   const canHover = hasHover();
 *
 *   // Show tooltip on hover for devices with hover capability
 *   // Show tooltip on click for touch devices
 *   return (
 *     <div>
 *       {children}
 *       {canHover ? (
 *         <HoverTooltip content={tooltip} />
 *       ) : (
 *         <ClickTooltip content={tooltip} />
 *       )}
 *     </div>
 *   );
 * }
 * ```
 */
export function hasHover(): boolean | null {
  if (!isBrowser()) {
    return null;
  }

  // Cache the result
  const cached = (hasHover as CachedFunction<boolean | null>)._cached;
  if (typeof cached === 'boolean') {
    return cached;
  }

  // Check for fine pointer (hover-capable devices)
  const hasFinePointer = window.matchMedia?.('(pointer: fine)').matches;

  // Check for hover capability explicitly
  const canHover = window.matchMedia?.('(hover: hover)').matches;

  const result = hasFinePointer || canHover;

  // Cache the result
  (hasHover as CachedFunction<boolean | null>)._cached = result;

  return result;
}

export { getBrowser } from './getBrowser';
export { getDevicePixelRatio } from './getDevicePixelRatio';
export { getOS } from './getOS';
export { getTextDirection } from './getTextDirection';
export { hasHover } from './hasHover';
export { isDesktop } from './isDesktop';
export { isMobile } from './isMobile';
export { isRTL } from './isRTL';
export { isTablet } from './isTablet';
export { isTouchDevice } from './isTouchDevice';

export type { Browser, DeviceType, OperatingSystem, TextDirection } from './platform.types';

import { isBrowser } from '../browser';

import { isMobile } from './isMobile';
import { isTablet } from './isTablet';

import type { CachedFunction } from './cache';

/**
 * Detects if the current device is a desktop.
 *
 * Returns true if the device is not mobile and not tablet.
 * This is cached for performance.
 *
 * **Key Features**:
 * - Inverse of mobile/tablet detection
 * - SSR-safe
 * - Cached result
 *
 * @returns True if device is desktop, false otherwise (null in SSR)
 *
 * @example
 * ```tsx
 * function DesktopOnlyFeature() {
 *   const isDesktopDevice = isDesktop();
 *
 *   if (!isDesktopDevice) {
 *     return null;
 *   }
 *
 *   return <AdvancedDataGrid />;
 * }
 * ```
 */
export function isDesktop(): boolean | null {
  if (!isBrowser()) {
    return null;
  }

  // Cache the result
  const cached = (isDesktop as CachedFunction<boolean | null>)._cached;
  if (typeof cached === 'boolean') {
    return cached;
  }

  const mobile = isMobile();
  const tablet = isTablet();

  // If either detection returns null (shouldn't happen since we checked isBrowser),
  // default to desktop
  if (mobile === null || tablet === null) {
    return true;
  }

  const result = !mobile && !tablet;

  // Cache the result
  (isDesktop as CachedFunction<boolean | null>)._cached = result;

  return result;
}

import { isBrowser } from '../browser';

import type { CachedFunction } from './cache';

/**
 * Detects if the current device is a mobile phone.
 *
 * Uses screen width and user agent detection to determine if the device
 * is a mobile phone. This is cached for performance.
 *
 * **Key Features**:
 * - User agent detection
 * - Screen width fallback
 * - SSR-safe
 * - Cached result
 *
 * @returns True if device is mobile, false otherwise (null in SSR)
 *
 * @example
 * ```tsx
 * function MobileMenu() {
 *   const isMobileDevice = isMobile();
 *
 *   if (isMobileDevice) {
 *     return <HamburgerMenu />;
 *   }
 *
 *   return <DesktopNav />;
 * }
 * ```
 *
 * @example
 * ```tsx
 * // With fallback rendering
 * function ResponsiveLayout() {
 *   const isMobileDevice = isMobile();
 *
 *   // During SSR, show desktop layout
 *   if (isMobileDevice === null) {
 *     return <DesktopLayout />;
 *   }
 *
 *   return isMobileDevice ? <MobileLayout /> : <DesktopLayout />;
 * }
 * ```
 */
export function isMobile(): boolean | null {
  if (!isBrowser()) {
    return null;
  }

  // Cache the result
  const cached = (isMobile as CachedFunction<boolean | null>)._cached;
  if (typeof cached === 'boolean') {
    return cached;
  }

  const userAgent = navigator.userAgent.toLowerCase();

  // Mobile patterns
  const mobilePatterns = [
    /android/i,
    /webos/i,
    /iphone/i,
    /ipod/i,
    /blackberry/i,
    /windows phone/i,
  ];

  const isMobileUA = mobilePatterns.some((pattern) => pattern.test(userAgent));

  // Check for tablet patterns (exclude from mobile)
  const isTabletUA =
    /ipad|tablet|playbook|silk/i.test(userAgent) ||
    (userAgent.includes('android') && !userAgent.includes('mobile'));

  // Use screen width as fallback (mobile typically < 768px)
  const isMobileWidth = window.innerWidth < 768;

  const result = !isTabletUA && (isMobileUA || isMobileWidth);

  // Cache the result
  (isMobile as CachedFunction<boolean | null>)._cached = result;

  return result;
}

import { isBrowser } from '../browser';

import type { CachedFunction } from './cache';

/**
 * Detects if the current document is in RTL (right-to-left) mode.
 *
 * Checks the document direction and html[dir] attribute.
 * This is cached for performance.
 *
 * **Key Features**:
 * - Checks document.dir
 * - Checks html[dir] attribute
 * - Computed style fallback
 * - SSR-safe
 * - Cached result
 *
 * @returns True if RTL, false if LTR (null in SSR)
 *
 * @example
 * ```tsx
 * function DirectionAwareIcon() {
 *   const rtl = isRTL();
 *
 *   return (
 *     <ChevronIcon
 *       style={{ transform: rtl ? 'scaleX(-1)' : undefined }}
 *     />
 *   );
 * }
 * ```
 *
 * @example
 * ```tsx
 * // RTL-aware margin
 * function Card() {
 *   const rtl = isRTL();
 *
 *   return (
 *     <div
 *       style={{
 *         marginLeft: rtl ? undefined : '16px',
 *         marginRight: rtl ? '16px' : undefined,
 *       }}
 *     >
 *       Content
 *     </div>
 *   );
 * }
 * ```
 */
export function isRTL(): boolean | null {
  if (!isBrowser()) {
    return null;
  }

  // Cache the result
  const cached = (isRTL as CachedFunction<boolean | null>)._cached;
  if (typeof cached === 'boolean') {
    return cached;
  }

  // Check document.dir
  if (document.dir) {
    const result = document.dir.toLowerCase() === 'rtl';
    (isRTL as CachedFunction<boolean | null>)._cached = result;
    return result;
  }

  // Check html[dir] attribute
  const htmlDir = document.documentElement.getAttribute('dir');
  if (htmlDir) {
    const result = htmlDir.toLowerCase() === 'rtl';
    (isRTL as CachedFunction<boolean | null>)._cached = result;
    return result;
  }

  // Check computed style
  const direction = window.getComputedStyle(document.documentElement).direction;
  const result = direction === 'rtl';

  // Cache the result
  (isRTL as CachedFunction<boolean | null>)._cached = result;

  return result;
}

import { isBrowser } from '../browser';

import type { CachedFunction } from './cache';

/**
 * Detects if the current device is a tablet.
 *
 * Uses user agent and screen width detection to determine if the device
 * is a tablet. This is cached for performance.
 *
 * **Key Features**:
 * - User agent detection for iPad, Android tablets
 * - Screen width fallback (768-1024px range)
 * - SSR-safe
 * - Cached result
 *
 * @returns True if device is tablet, false otherwise (null in SSR)
 *
 * @example
 * ```tsx
 * function TabletOptimizedView() {
 *   const isTabletDevice = isTablet();
 *
 *   if (isTabletDevice) {
 *     return <TwoColumnLayout />;
 *   }
 *
 *   return <SingleColumnLayout />;
 * }
 * ```
 */
export function isTablet(): boolean | null {
  if (!isBrowser()) {
    return null;
  }

  // Cache the result
  const cached = (isTablet as CachedFunction<boolean | null>)._cached;
  if (typeof cached === 'boolean') {
    return cached;
  }

  const userAgent = navigator.userAgent.toLowerCase();

  // Tablet patterns
  const tabletPatterns = [/ipad/i, /tablet/i, /playbook/i, /silk/i];

  const isTabletUA =
    tabletPatterns.some((pattern) => pattern.test(userAgent)) ||
    (userAgent.includes('android') && !userAgent.includes('mobile'));

  // Use screen width as fallback (tablet typically 768-1024px)
  const isTabletWidth = window.innerWidth >= 768 && window.innerWidth <= 1024;

  const result =
    isTabletUA ||
    (!navigator.userAgent.match(/android|iphone|ipod|blackberry|windows phone/i) && isTabletWidth);

  // Cache the result
  (isTablet as CachedFunction<boolean | null>)._cached = result;

  return result;
}

import { isBrowser } from '../browser';

import type { CachedFunction } from './cache';

interface NavigatorWithMS extends Navigator {
  msMaxTouchPoints?: number;
}

/**
 * Detects if the current device has touch capability.
 *
 * Checks for touch event support and pointer type. Note that some devices
 * support both touch and mouse (e.g., Surface with touch screen).
 *
 * **Key Features**:
 * - Touch event API detection
 * - Pointer type detection
 * - Max touch points check
 * - SSR-safe
 * - Cached result
 *
 * @returns True if device supports touch, false otherwise (null in SSR)
 *
 * @example
 * ```tsx
 * function InteractiveElement() {
 *   const hasTouch = isTouchDevice();
 *
 *   return (
 *     <button
 *       // Larger touch target for touch devices
 *       style={{ minHeight: hasTouch ? '44px' : '32px' }}
 *     >
 *       Click me
 *     </button>
 *   );
 * }
 * ```
 *
 * @example
 * ```tsx
 * // Conditional gesture handling
 * function DraggableItem() {
 *   const hasTouch = isTouchDevice();
 *
 *   return (
 *     <div
 *       onTouchStart={hasTouch ? handleTouchStart : undefined}
 *       onMouseDown={!hasTouch ? handleMouseDown : undefined}
 *     >
 *       Drag me
 *     </div>
 *   );
 * }
 * ```
 */
export function isTouchDevice(): boolean | null {
  if (!isBrowser()) {
    return null;
  }

  // Cache the result
  const cached = (isTouchDevice as CachedFunction<boolean | null>)._cached;
  if (typeof cached === 'boolean') {
    return cached;
  }

  const hasTouchEvents =
    'ontouchstart' in window ||
    navigator.maxTouchPoints > 0 ||
    ((navigator as NavigatorWithMS).msMaxTouchPoints ?? 0) > 0;

  const hasCoarsePointer = window.matchMedia?.('(pointer: coarse)').matches;

  const result = hasTouchEvents || hasCoarsePointer;

  // Cache the result
  (isTouchDevice as CachedFunction<boolean | null>)._cached = result;

  return result;
}

/**
 * Operating system types.
 */
export type OperatingSystem = 'iOS' | 'Android' | 'Windows' | 'macOS' | 'Linux' | 'Unknown';

/**
 * Browser types.
 */
export type Browser = 'Chrome' | 'Firefox' | 'Safari' | 'Edge' | 'Opera' | 'Samsung' | 'Unknown';

/**
 * Text direction types.
 */
export type TextDirection = 'ltr' | 'rtl';

/**
 * Device type.
 */
export type DeviceType = 'mobile' | 'tablet' | 'desktop';
